<?php
namespace App\Domain\AI\Launchpad\Services;
use App\Domain\AI\Agents\Data\CreateAgentDraftData;use App\Domain\AI\Agents\Models\Agent;use App\Domain\AI\Agents\Services\CreateAgentDraftService;use App\Domain\AI\Core\{AiEntitlementGate,AiFeatureGate};use App\Domain\AI\Launchpad\Data\LaunchpadRecommendationData;use App\Domain\AI\Launchpad\Enums\LaunchpadSessionStatus;use App\Domain\AI\Launchpad\Models\AgentLaunchpadSession;use App\Domain\AI\Tenancy\AiTenantBoundary;use App\Domain\Network\Tenancy\TenantAccessService;use App\Models\User;use Illuminate\Auth\Access\AuthorizationException;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
final class ConvertLaunchpadSessionToAgentDraftService
{
 public function __construct(private AiFeatureGate$features,private AiTenantBoundary$tenants,private AiEntitlementGate$entitlements,private TenantAccessService$access,private CreateAgentDraftService$drafts){}
 public function convert(User$actor,AgentLaunchpadSession$session):Agent{$this->features->ensureEnabled();$this->tenants->assertResourceBelongsToCurrentTenant($session);$this->entitlements->ensureAllowed();if(!$this->access->canManageTenant($actor))throw new AuthorizationException('Only an active owner or admin may create an agent draft.');return DB::transaction(function()use($actor,$session){$locked=AgentLaunchpadSession::query()->whereKey($session->id)->lockForUpdate()->firstOrFail();if($locked->status===LaunchpadSessionStatus::Converted){$agent=$locked->convertedAgent()->first();if(!$agent)throw ValidationException::withMessages(['launchpad'=>'El borrador convertido ya no está disponible.']);return$agent;}if($locked->status!==LaunchpadSessionStatus::Recommended)throw ValidationException::withMessages(['launchpad'=>'La propuesta no está lista para convertirse.']);try{$r=LaunchpadRecommendationData::fromArray($locked->recommendation??[]);}catch(\Throwable){throw ValidationException::withMessages(['launchpad'=>'La propuesta guardada no es válida. Genera una nueva recomendación.']);}$code='LP-'.strtoupper(str_replace('-','',substr($locked->uuid,0,18)));$created=$this->drafts->create($actor,new CreateAgentDraftData($code,$r->suggestedName,$r->jobToBeDone,$r->recommendedAgentType,$r->contract(),$r->configuration()));$locked->markConverted($created->agent,$actor);return$created->agent;});}
}
